const fs=require('node:fs');
const {decode}=require('./line-1/media/finish-wall.cjs');
const a=decode(fs.readFileSync('artifacts/line-1/wall-v11.png'));
const b=decode(fs.readFileSync('artifacts/line-1/wall-v12.png'));
let protectedCount=0, changed=0, outside=0;
for(let y=0;y<1254;y++)for(let x=0;x<1254;x++){
 const inside=x>212&&x<333&&y>329&&y<448&&!(x>=310&&y<=367)&&!(x>=310&&y>=426);
 const i=(y*1254+x)*3;
 const differs=!a.pixels.subarray(i,i+3).equals(b.pixels.subarray(i,i+3));
 if(!inside){protectedCount++;if(differs)outside++;}
 if(differs)changed++;
}
if(outside||changed<1000||protectedCount!==1559736)throw Error('preservation failed');
console.log(JSON.stringify({protected_pixels:protectedCount,changed_pixels:changed,outside_mask_changed_pixels:outside}));
